<!--vbase-->
<template>
  <SubHeader
    name="classification"
    :label="$t('classification')"
    :display_help_link="false"
  />

  <div class="row q-col-gutter-md q-pa-md height-100vh-40px">
    <div class="col-12 col-md-9">
      <div class="back-white full-height classify-panel">
        <iframe
          :src="path"
          title="Main menu"
          class="classify-iframe"
        ></iframe>
      </div>
    </div>

    <div class="col-12 col-md-3">
      <div class="back-white full-height classify-panel column">
        <div class="text-red-13 text-h6 text-weight-bold text-center q-pa-md">
          {{ $t('details') }}
        </div>
        <q-separator />
        <div class="col scroll q-pa-md">
          <div class="q-mb-sm">
            <div class="text-weight-bold">Classification Class</div>
            <div>{{ classification.classification_label_class || '-' }}</div>
          </div>

          <div class="q-mb-md">
            <div class="text-weight-bold">Classification Label</div>
            <div>{{ classification.classification_label || '-' }}</div>
          </div>

          <q-separator class="q-mb-md" />

          <div class="text-weight-bold q-mb-sm">
            {{ $t('Re-Classifiy Document') }}
          </div>
          <labelsDropdown />

          <q-btn
            class="q-mt-md full-width"
            :label="$t('proceed')"
            color="primary"
            @click="restartDoc"
          />
        </div>
      </div>
    </div>
  </div>
  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import { DOC2API_URL } from 'src/pages/APIs';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { documentDetailApiService } from 'src/services';
import { useImageAuth } from 'src/composables/useImageAuth';
import { notify } from 'src/components/notifications/notify';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import labelsDropdown from 'src/components/document/classification/labels_dropdown.vue';

import {
  useDocumentStore,
  useDocClassificationStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [cache],
  components: {
    SubHeader,
    labelsDropdown,
  },
  mounted() {
    this.init();
  },

  unmounted: function () {
    // unmounted
  },
  data() {
    return {
      docId: '',
      filename: '',
    };
  },
  methods: {
    async init() {
      try {
        await this.getTokenQueryParam();
        this.processing = true;
        this.docId = this.$route.params.id as string;
        this.filename = this.$route.params.filename as string;
        this.path =
          DOC2API_URL +
          '/resource/document/' +
          this.docId +
          '/' +
          this.docId +
          '.pdf?download=false' +
          '&' +
          this.tokenQueryParam;

        if (!this.path) {
          logInfo('pdf not found');
        }

        await this.getInvoiceDataByDocId(this.docId);
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          return;
        }
        this.classification = this.record.classification;
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        this.record = [];
        await this.getDocumentById(docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async restartDoc() {
      try {
        this.processing = true;
        let data = {} as dynamicObj;

        if (this.selected_custom_model_label) {
          data.doc_classification_label = this.selected_custom_model_label;
        }

        await documentDetailApiService.restartClassification(data, this.docId);
        this.resetStore();
        notify.success(this.$t('NEW_CLASSIFICATION'));
        this.$router.push('/dashboard');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doctype, error } = storeToRefs(doc_store);
    const { getDocumentById, setRecordFromCache } = doc_store;

    const classification_store = useDocClassificationStore();
    const { resetStore } = classification_store;
    const { selected_custom_model_label } = storeToRefs(classification_store);

    const { tokenQueryParam, refreshTokenParam } = useImageAuth();

    return {
      resetStore,
      selected_custom_model_label,
      getDocumentById,
      getTokenQueryParam: refreshTokenParam,
      setRecordFromCache,
      path: ref(''),
      processing: ref(false),
      record,
      doctype,
      error,
      classification: ref({} as any),
      tokenQueryParam,
    };
  },
});
</script>

<style lang="scss" scoped>
.classify-panel {
  height: 100%;
  border-radius: 4px;
  overflow: hidden;
}

.classify-iframe {
  width: 100%;
  height: 100%;
  border: 0;
  display: block;
}
</style>
